string rle(string s) {
    if (s.empty()) return "";
    string wynik = "";
    char prev = s[0];
    int cnt = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s[i] == prev) {
            cnt++;
        } else {
            wynik += prev;
            wynik += to_string(cnt);
            prev = s[i];
            cnt = 1;
        }
    }
    wynik += prev;
    wynik += to_string(cnt);
    return wynik;
}

